parameters.jsonBody:
={{
{
  "model": $json.groq_model,
  "temperature": 0,
  "response_format": {
    "type": "json_object"
  },
  "messages": [
    {
      "role": "system",
      "content": "You are a legal document analysis assistant specialized in Turkish legal and contractual documents (court notices, appeals, objections, contracts).

Given the full text of a document, extract the following and respond with ONLY a valid JSON object — no markdown, no explanation, no preamble.

Output schema:
{
  "doc_type": "durusma_tebligati | itiraz_bildirimi | temyiz_bildirimi | sozlesme | other",
  "parties": ["string", ...],
  "summary": "2-3 sentence summary in Turkish of what the document is about and what it requires",
  "reference_date": "YYYY-MM-DD or null — the notification/service date (tebliğ tarihi) if present, used to compute relative deadlines",
  "critical_dates": [
    {
      "date_type": "durusma | itiraz_suresi | temyiz_suresi | sozlesme_yenileme",
      "quote": "exact text span from the document that mentions this date",
      "explicit_date": "YYYY-MM-DD or null if the date is not written explicitly",
      "computed_date": "YYYY-MM-DD or null if it cannot be confidently computed",
      "confidence": 0.0,
      "needs_human_review": true,
      "meaning": "short explanation in Turkish of what happens on/by this date",
      "reminder_days_before": 7
    }
  ]
}

Rules:
1. Only extract these 4 date types: durusma, itiraz_suresi, temyiz_suresi, sozlesme_yenileme. Ignore all other dates in the document.
2. If a date is stated explicitly (e.g. "14.03.2027 tarihinde"), set both explicit_date and computed_date to that value, confidence >= 0.9, needs_human_review: false.
3. If a date must be computed from a relative expression (e.g. "tebliğden itibaren 7 gün içinde"), and reference_date is present and unambiguous in the document, compute computed_date = reference_date + N days and set confidence around 0.6-0.7, needs_human_review: true.
4. If a relative date cannot be computed with reasonable confidence (missing reference_date, ambiguous wording, unclear whether calendar days or business days), set computed_date to null, confidence below 0.5, needs_human_review: true. Do NOT guess.
5. Never silently assume "gün" means business days or calendar days — if the document doesn't specify, lower confidence and flag for human review, since legal deadline miscalculation has real consequences.
6. If the document has no relevant critical dates, return an empty critical_dates array.
7. Respond in valid JSON only."
    },
    {
      "role": "user",
      "content": "DOCUMENT_TEXT:

" + $json.document_text
    }
  ]
}
}}

parameters.jsCode:
const raw = $json.choices[0].message.content;
let parsed;
try {
  parsed = JSON.parse(raw);
} catch (e) {
  throw new Error('Groq returned invalid JSON: ' + raw.slice(0, 200));
}
if (!Array.isArray(parsed.critical_dates)) {
  parsed.critical_dates = [];
}
parsed.file_name = $('Config: Workflow Settings').item.json.file_name;
parsed.file_id = $('Config: Workflow Settings').item.json.file_id;
parsed.confidence_threshold = $('Config: Workflow Settings').item.json.confidence_threshold;
parsed.telegram_chat_id = $('Config: Workflow Settings').item.json.telegram_chat_id;
return [{ json: parsed }];

const d = $json;
const dates = d.critical_dates || [];

let dateLines;
if (dates.length === 0) {
  dateLines = 'Bu belgede kritik tarih tespit edilmedi.';
} else {
  dateLines = dates.map(c =>
    `• ${c.date_type}: ${c.computed_date || 'Hesaplanamadı ❓'} (güven: ${c.confidence})${c.needs_human_review ? ' — ⚠️ Kontrol gerekli' : ''}`
  ).join('\n');
}

const reviewCount = dates.filter(c => c.needs_human_review).length;
const riskNote = dates.length === 0
  ? ''
  : reviewCount > 0
    ? `\n⚠️ ${reviewCount} tarih manuel kontrol gerektiriyor.`
    : '\n✅ Tüm tarihler yeterli güvenle hesaplandı.';

const text = `📄 *Yeni Belge İşlendi*\n*Dosya:* ${d.file_name}\n*Tür:* ${d.doc_type}\n*Taraflar:* ${(d.parties || []).join(', ') || '—'}\n\n*Özet:* ${d.summary}\n\n📅 *Kritik Tarihler:*\n${dateLines}${riskNote}`;

return [{ json: { text, chat_id: d.telegram_chat_id } }];

const err = $json.error || $json;
const errorMessage = typeof err === 'string' ? err : (err.message || JSON.stringify(err).slice(0, 300));

let fileName = 'Unknown file';
try {
  fileName = $('Config: Workflow Settings').item.json.file_name;
} catch (e) {}

let chatId = null;
try {
  chatId = $('Config: Workflow Settings').item.json.telegram_chat_id;
} catch (e) {}

const text = `🚨 *Workflow Error*\nFile: ${fileName}\nStep: ${$node.name}\nError: ${errorMessage}`;

return [{ json: { text, chat_id: chatId } }];
